/* Задачник 3.0 — интерфейс без внешних зависимостей. */
'use strict';
const h=(x='')=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>Z.validDate(d)?d.split('-').reverse().join('.'):'—';
const span=(a,b)=>fmt(a)+' — '+fmt(b);
const plain=x=>h(x||'—').replace(/\n/g,'<br>');
const short=(s,n=105)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':s||'';
const iconPaths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',planning:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-14 5h4"/>',tasks:'<path d="m3 6 2 2 4-4m3 2h9M3 13l2 2 4-4m3 2h9M3 20l2 2 4-4m3 2h9"/>',projects:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 4h6a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',analytics:'<path d="M4 3v18h17M8 16l4-6 4 3 5-8"/>',crm:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',meetings:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V5a2 2 0 0 1 2-2h8a8 8 0 0 1 8 8Z"/><path d="M7 8h9m-9 5h6"/>',reports:'<path d="M5 3h10l4 4v14H5V3Zm10 0v5h4M8 12h8m-8 4h6"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',panel:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16m5-11 3 3-3 3"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m4 12 5 5L20 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=k=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.tasks}</svg>`;
const pages={dashboard:['Обзор','Вся работа — в одном месте.'],tasks:['Задачи','Активная работа, сроки и результаты.'],projects:['Проекты','Постоянные проекты и направления.'],planning:['Планирование','Фокус между двумя супервизиями.'],analytics:['Аналитика','Что изменилось за выбранный период.'],crm:['CRM ПСТБИ','Состояние базы на конкретную дату.'],meetings:['Супервизии','Результаты встреч и следующие шаги.'],reports:['Отчёт','Работа и результаты за выбранный период.'],settings:['Настройки','Данные, резервные копии и помощь.']};
let state=ZStore.init(ZSEED).state;
const now=Z.today(),month=Z.calendarMonth(now);
const latestMeeting=()=>state?.meetings.filter(m=>m.date&&m.date<=Z.today()).sort((a,b)=>b.date.localeCompare(a.date))[0];
const latest=latestMeeting();
const pref=(k,fallback)=>{try{return localStorage.getItem(k)??fallback;}catch{return fallback;}};
const ui={page:'dashboard',collapsed:pref('supervision-menu-collapsed','false')==='true',mobile:false,from:latest&&latest.date<now?Z.addDays(latest.date,1):month[0],to:now,planFrom:now,planTo:Z.addDays(now,30),planSearch:'',filters:{status:'active',time:'all',dateField:'deadline',direction:'all',project:'',search:'',type:''},modal:null,editId:null,draft:null,error:'',statusDate:now,crmId:'',crmMonth:'',meetingId:'',reportMeetingId:'',reportId:'',periodDraft:null,importData:null,importName:'',savingError:'',savedLabel:'Сохранено',tabNotice:''};
ui.dashboardFilters=Z.clone(ui.filters);
const currentFilters=()=>ui.page==='dashboard'?ui.dashboardFilters:ui.filters;
const pName=code=>Z.project(state,code)?.name||code;
const dName=t=>Z.direction(state,t)||'Прочее';
const badge=s=>`<span class="badge ${s==='Завершено'?'green':['Провалено','Заблокировано'].includes(s)?'red':s==='В работе'?'indigo':'neutral'}">${h(s)}</span>`;
const act=(action,label,value='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-value="${h(value)}">${label}</button>`;
const empty=(text='Здесь пока ничего нет.')=>`<div class="empty">${h(text)}</div>`;
const opt=(values,selected)=>values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${h(v)}" ${v===selected?'selected':''}>${h(l)}</option>`;}).join('');
const input=(label,id,value,type='text',extra='')=>`<label class="field"><span>${h(label)}</span><input id="${id}" data-focus="${id}" type="${type}" value="${h(value)}" ${extra}></label>`;
const area=(label,id,value,extra='')=>`<label class="field"><span>${h(label)}</span><textarea id="${id}" data-focus="${id}" rows="3" ${extra}>${h(value)}</textarea></label>`;
const select=(label,id,values,value,extra='')=>`<label class="field"><span>${h(label)}</span><select id="${id}" data-focus="${id}" ${extra}>${opt(values,value)}</select></label>`;
const heading=(title,extra='',subtitle='')=>`<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${extra}</div>`;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),4000);}
function commit(fn,{renderNow=true}={}){try{const v=ZStore.transaction(fn);state=ZStore.state;ui.savingError='';ui.savedLabel='Сохранено';if(renderNow)render();return {ok:true,value:v};}catch(e){ui.savingError=e.message;ui.savedLabel='Не сохранено';toast(e.message,true);if(renderNow)render();return {ok:false};}}
function render(){
 const a=document.activeElement,focus=a?.dataset.focus,pos=a?.selectionStart,end=a?.selectionEnd,scroll=a?.scrollTop;const modalScroll=document.querySelector('.modal')?.scrollTop||0;
 if(!state){document.querySelector('#app').innerHTML=recovery();return;}
 const [title,subtitle]=pages[ui.page];
 document.querySelector('#app').innerHTML=`<div class="shell ${ui.collapsed?'collapsed':''} ${ui.mobile?'menu-open':''}"><button class="scrim" data-action="mobile-close" aria-label="Закрыть меню"></button><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-value="dashboard"><img src="icon.svg" width="40" height="40" alt=""><span><b>Задачник</b><small>Работа в своём ритме</small></span></a><nav aria-label="Разделы">${Object.entries(pages).map(([key,v])=>`<button data-action="nav" data-value="${key}" class="nav-item ${key===ui.page?'selected':''}" ${key===ui.page?'aria-current="page"':''} title="${v[0]}">${icon(key)}<span>${v[0]}</span></button>`).join('')}</nav><div class="sidebar-bottom">${act('collapse',icon('panel')+'<span>Свернуть меню</span>','','collapse-btn')}<small>Задачник · 3.0</small></div></aside><main><div class="workspace"><button class="icon-btn mobile-only" data-action="mobile-open" aria-label="Открыть меню">${icon('panel')}</button><span>МОЁ ПРОСТРАНСТВО <i>/</i> ${h(title)}</span><span class="save-status ${ui.savingError?'error-text':''}" role="status">${ui.savingError?'Не сохранено':ui.savedLabel}${!ui.savingError?icon('check'):''}</span></div>${ui.savingError?`<div class="notice danger">${h(ui.savingError)}</div>`:''}${ui.tabNotice?`<div class="notice">${h(ui.tabNotice)} ${act('dismiss-tab','Понятно','','small')}</div>`:''}<header class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${toolbar()}</div></header><div id="page-content">${renderPage()}</div><footer class="page-footer">Задачник · 3.0</footer></main></div>${renderModal()}`;
 if(focus){const el=[...document.querySelectorAll('[data-focus]')].find(x=>x.dataset.focus===focus);if(el){el.focus({preventScroll:true});if(pos!==null&&pos!==undefined&&['text','search','textarea'].includes(el.type))try{el.setSelectionRange(pos,end);}catch{}el.scrollTop=scroll||0;}}
 const m=document.querySelector('.modal');if(m)m.scrollTop=modalScroll;
}
function toolbar(){if(['dashboard','tasks'].includes(ui.page))return act('new-task',icon('plus')+'Добавить задачу','','primary');if(ui.page==='projects')return act('new-project',icon('plus')+'Проект','','primary');if(ui.page==='crm')return act('new-crm',icon('plus')+'Новый срез','','primary');if(ui.page==='meetings')return act('new-meeting',icon('plus')+'Супервизия','','primary');return '';}
function renderPage(){return ({dashboard:dashboard,tasks:tasksPage,projects:projectsPage,planning:planningPage,analytics:analyticsPage,crm:crmPage,meetings:meetingsPage,reports:reportsPage,settings:settingsPage})[ui.page]();}
function kpi(label,value,hint='',tone=''){return `<div class="kpi ${tone}"><span>${h(label)}</span><strong>${value}</strong><small>${h(hint)}</small></div>`;}
function taskRows(tasks,{limit=null,compact=false}={}){const rows=limit?tasks.slice(0,limit):tasks;return rows.length?`<div class="task-list ${compact?'compact':''}">${rows.map(t=>`<div class="task-row"><button class="task-open" data-action="task" data-value="${h(t.id)}"><span class="task-symbol ${t.status==='Завершено'?'done':''}">${t.status==='Завершено'?icon('check'):t.type==='Группа задач'?icon('projects'):''}</span><span class="task-copy"><b>${h(t.title)}</b><small>${h(t.id)} <i>·</i> ${h(pName(t.projectCode))}</small>${t.result&&t.status==='Завершено'?`<span class="result-preview">${h(short(t.result))}</span>`:''}</span></button><span class="row-meta">${t.deadline?`<span class="due ${Z.isActive(t)&&t.deadline<Z.today()?'late':''}">${fmt(t.deadline)}</span>`:''}${badge(t.status)}</span></div>`).join('')}</div>`:empty('Задач нет.');}
function dashboard(){
 const active=state.tasks.filter(t=>Z.isActive(t)&&Z.isWork(t));const last=latestMeeting();const since=last?Z.addDays(last.date,1):'';const completed=since&&since<=Z.today()?Z.metrics(state,since,Z.today()).completed:[];
 const overdue=active.filter(t=>t.deadline&&t.deadline<Z.today()).sort((a,b)=>a.deadline.localeCompare(b.deadline));const soon=active.filter(t=>Z.between(t.deadline,Z.today(),Z.addDays(Z.today(),6))).sort((a,b)=>a.deadline.localeCompare(b.deadline));
 const nextDates=state.meetings.flatMap(m=>[m.date,m.nextMeeting]).filter(d=>d>Z.today()).sort();const updates=state.updates.filter(u=>Z.between(u.date,Z.addDays(Z.today(),-13),Z.today())).length;
 return `<div class="supervision-strip"><div><span class="eyebrow">Рабочий ритм</span><b>От встречи к результату</b></div><div><small>Последняя супервизия</small><strong>${fmt(last?.date)}</strong></div><div><small>Следующая</small><strong>${fmt(nextDates[0])}</strong></div>${act('current-report','Открыть отчёт '+icon('arrow'),'','quiet')}</div><div class="kpis">${kpi('Активные задачи',active.length,'без групп и предложений')}${kpi('Завершено после встречи',completed.length,last?'после '+fmt(last.date):'добавьте дату супервизии','success')}${kpi('Просрочено',overdue.length,'требуют внимания',overdue.length?'danger':'')}${kpi('Записей о работе',updates,'за последние 14 дней')}</div><div class="grid two attention"><section class="card">${heading('Требуют внимания',`<span class="count ${overdue.length?'red':''}">${overdue.length}</span>`,'Просроченные активные задачи')}${overdue.length?taskRows(overdue,{limit:5}):empty('Просроченных задач нет.')}${overdue.length>5?act('overdue','Все просрочки','','text-btn'):''}</section><section class="card">${heading('Ближайшие 7 дней',`<span class="count">${soon.length}</span>`,span(Z.today(),Z.addDays(Z.today(),6)))}${soon.length?taskRows(soon,{limit:5}):empty('На эту неделю дедлайнов нет.')}${soon.length>5?act('week','Все сроки недели','','text-btn'):''}</section></div><section class="card">${heading('Завершено после супервизии',last?act('completed-since','Все результаты '+icon('arrow'),'','text-btn'):act('new-meeting','Добавить супервизию','','small'))}${last?(completed.length?taskRows([...completed].sort((a,b)=>b.eventDate.localeCompare(a.eventDate)),{limit:5}):empty('После этой встречи завершений пока нет.')):empty('Укажите дату прошедшей супервизии, чтобы видеть результаты после неё.')}</section><section>${heading('Активная работа по направлениям','', 'Все активные задачи независимо от отчётного периода')}<div class="direction-grid">${[...new Set([...Z.DIRECTIONS,...state.projects.map(p=>p.direction),''])].map(d=>{const list=active.filter(t=>Z.direction(state,t)===d);return `<button class="direction-card" data-action="direction" data-value="${h(d||'__other')}"><span>${h(d||'Прочее')}</span><strong>${list.length}</strong><small>${list.filter(t=>t.status==='В работе').length} в работе ${icon('arrow')}</small></button>`;}).join('')}</div><div class="card active-preview">${filtersBar('dashboard')}${taskRows(filteredTasks().filter(t=>t.type==='Задача'))}</div></section><section class="card">${heading('Последний срез CRM',act('nav','Открыть CRM '+icon('arrow'),'crm','text-btn'))}${crmComparison(null,Z.latestCrm(state),false)}</section>`;
}
function filtersBar(prefix='tasks'){const f=currentFilters();return `<div class="filters">${input('Поиск',prefix+'Search',f.search,'search','placeholder="Название, ID или проект" data-filter="search"')}${select('Статус',prefix+'Status',[['all','Все задачи'],['active','Все активные'],['completed','Все завершённые'],['failed','Все проваленные'],['cancelled','Отменённые'],['archived','Архив']],f.status,'data-filter="status"')}${select('Период',prefix+'Time',[['all','Любое время'],['week',f.dateField==='completedAt'?'Последние 7 дней':'Ближайшие 7 дней'],['month','Текущий месяц'],['overdue','Просроченные']],f.time,'data-filter="time"')}${select('Фильтровать по',prefix+'DateField',[['deadline','Дедлайну'],['completedAt','Дате завершения']],f.dateField,'data-filter="dateField"')}${select('Направление',prefix+'Direction',[['all','Все направления'],...new Set([...Z.DIRECTIONS,...state.projects.map(p=>p.direction).filter(Boolean)]),['__other','Прочее']],f.direction,'data-filter="direction"')}${prefix==='tasks'?select('Проект','taskProjectFilter',[['','Все проекты'],...state.projects.map(p=>[p.code,p.name])],f.project,'data-filter="project"')+select('Тип','taskTypeFilter',[['','Все типы'],...Z.TYPES],f.type,'data-filter="type"'):''}</div>`;}
function filteredTasks(){const f=currentFilters();return state.tasks.filter(t=>{
 if(f.status==='archived'?!t.archived:t.archived)return false;
 if(f.status==='active'&&!Z.isActive(t)||f.status==='completed'&&t.status!=='Завершено'||f.status==='failed'&&t.status!=='Провалено'||f.status==='cancelled'&&t.status!=='Отменено')return false;
 if(f.project&&t.projectCode!==f.project||f.type&&t.type!==f.type)return false;
 if(f.direction!=='all'&&Z.direction(state,t)!==(f.direction==='__other'?'':f.direction))return false;
 const d=t[f.dateField];const weekFrom=f.dateField==='completedAt'?Z.addDays(Z.today(),-6):Z.today(),weekTo=f.dateField==='completedAt'?Z.today():Z.addDays(Z.today(),6);if(f.time==='week'&&!Z.between(d,weekFrom,weekTo)||f.time==='month'&&(!d||d.slice(0,7)!==Z.today().slice(0,7))||f.time==='overdue'&&(!Z.isActive(t)||!t.deadline||t.deadline>=Z.today()))return false;
 return (t.title+' '+t.id+' '+pName(t.projectCode)).toLowerCase().includes(f.search.toLowerCase());
 }).sort((a,b)=>Number(!Z.isActive(a))-Number(!Z.isActive(b))||(a.deadline||'9999').localeCompare(b.deadline||'9999')||a.id.localeCompare(b.id,'ru',{numeric:true}));}
function tasksPage(){const rows=filteredTasks();return `<section class="card">${filtersBar()}<div class="list-caption"><span>${rows.length} записей</span><span>Группы и предложения не входят в показатели выполнения</span></div>${rows.length?`<div class="table-wrap"><table class="tasks-table"><thead><tr><th>Задача</th><th>Проект</th><th>Статус</th><th>Срок</th><th>Результат</th></tr></thead><tbody>${rows.map(t=>`<tr><td><button class="table-title" data-action="task" data-value="${h(t.id)}">${h(t.title)}</button><div class="id-line"><span>${h(t.id)}</span><button class="icon-btn" data-action="copy" data-value="${h(t.id)}" aria-label="Копировать ID ${h(t.id)}">${icon('copy')}</button>${t.parentId?act('task','↳ '+h(t.parentId),t.parentId,'text-btn small'):''}</div>${t.type!=='Задача'?`<small class="muted">${h(t.type)}${t.type==='Группа задач'?' · '+groupProgress(t.id):''}</small>`:''}</td><td>${h(pName(t.projectCode))}<small class="muted block">${h(dName(t))}</small></td><td>${badge(t.status)}${t.archived?'<small class="muted block">В архиве</small>':''}</td><td><span class="${Z.isActive(t)&&t.deadline&&t.deadline<Z.today()?'late':''}">${fmt(t.deadline)}</span>${t.priority?`<small class="muted block">${h(t.priority)} приоритет</small>`:''}</td><td class="result-cell">${h(short(t.result)||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('Нет задач с такими условиями. Попробуйте изменить фильтры.')}</section>`;}
function groupProgress(id){const ids=Z.descendants(state,id),ts=state.tasks.filter(t=>ids.has(t.id)&&Z.isWork(t));return `${ts.filter(t=>t.status==='Завершено').length} / ${ts.length} завершено`;}
function projectsPage(){return [...new Set([...Z.DIRECTIONS,...state.projects.map(p=>p.direction),''])].map(d=>{const ps=state.projects.filter(p=>(p.direction||'')===d);return `<section>${heading(h(d||'Прочее'),`<span class="count">${ps.length}</span>`)}<div class="project-grid">${ps.map(p=>{const ts=state.tasks.filter(t=>t.projectCode===p.code&&Z.isWork(t)&&!t.archived);return `<article class="card project-card"><span class="eyebrow">${h(p.code)} · ${h(p.type||'Проект')}</span><h3>${h(p.name)}</h3><p class="muted">${ts.filter(Z.isActive).length} активных · ${ts.filter(t=>t.status==='Завершено').length} завершено</p><div class="actions">${act('project-tasks','Задачи',p.code,'small')}${act('project-edit','Изменить',p.code,'small quiet')}${act('project-new-task',icon('plus'),p.code,'small')}</div></article>`;}).join('')||`<div class="card">${empty('Проекты без направления будут показаны здесь.')}</div>`}</div></section>`;}).join('');}
function periodPicker(planning=false){const draft=ui.periodDraft?.planning===planning?ui.periodDraft:null;const from=draft?.from??(planning?ui.planFrom:ui.from),to=draft?.to??(planning?ui.planTo:ui.to);return `<form class="card period-bar" data-form="period" data-planning="${planning}"><div class="period-caption"><span class="eyebrow">${planning?'Период планирования':'Период отчётности'}</span><b>${span(planning?ui.planFrom:ui.from,planning?ui.planTo:ui.to)}</b></div><div class="period-fields">${input('С','periodFrom',from,'date','required data-period="from"')}${input('По','periodTo',to,'date',`required data-period="to" ${planning?'':`max="${Z.today()}"`}`)}<button class="btn primary" type="submit">Применить</button></div><div class="presets">${act('preset','Неделя',planning?'plan-week':'week','text-btn small')}${act('preset','Месяц',planning?'plan-month':'month','text-btn small')}${!planning?act('preset','После супервизии','meeting','text-btn small'):''}<small>Обе даты включены</small></div>${ui.periodDraft?.error?`<p class="error-text">${h(ui.periodDraft.error)}</p>`:''}</form>`;}
function cycle(){return state.cycles.find(c=>c.startDate===ui.planFrom&&c.endDate===ui.planTo);}
function ensureCycle(d){let c=d.cycles.find(c=>c.startDate===ui.planFrom&&c.endDate===ui.planTo);if(!c){c={id:Z.uid(),startDate:ui.planFrom,endDate:ui.planTo,focus:'',notes:'',taskIds:[]};d.cycles.push(c);}return c;}
function planningPage(){const c=cycle(),selected=(c?.taskIds||[]).map(id=>Z.task(state,id)).filter(Boolean),candidates=state.tasks.filter(t=>Z.isActive(t)&&!c?.taskIds.includes(t.id)&&(t.title+' '+t.id).toLowerCase().includes(ui.planSearch.toLowerCase()));const row=(t,inPlan)=>`<div class="plan-row"><button class="task-open" data-action="task" data-value="${h(t.id)}"><span class="task-copy"><b>${h(t.title)}</b><small>${h(t.id)} · ${h(t.status)}</small></span></button>${act(inPlan?'plan-remove':'plan-add',inPlan?'Убрать':'+ В план',t.id,'small')}</div>`;return `${periodPicker(true)}${state.cycles.length?`<div class="saved-plan-picker">${select('Сохранённые периоды','planSelect',[['','Выберите период'],...state.cycles.map(c=>[c.id,span(c.startDate,c.endDate)])],c?.id||'','data-ui="planId"')}</div>`:''}<section class="card">${area('Фокус периода','cycleFocus',c?.focus||'','placeholder="Какой результат важен к следующей встрече?" data-cycle="focus"')}<p class="muted small">Задачи остаются общими. Добавление в план не создаёт копию.</p></section><div class="grid two"><section class="card">${heading('В плане',`<span class="count">${selected.length}</span>`)}${selected.map(t=>row(t,true)).join('')||empty('Добавьте задачи из списка справа.')}</section><section class="card">${heading('Добавить задачи',act('new-task',icon('plus')+'Новая','','small'))}${input('Поиск','planSearch',ui.planSearch,'search','data-ui="planSearch" placeholder="Название или ID"')}<div class="scroll-list">${candidates.map(t=>row(t,false)).join('')||empty('Подходящих активных задач нет.')}</div></section></div>`;}
function metricCards(r){return `<div class="kpis">${kpi('Завершено',r.completed.length,'завершения за период','success')}${kpi('Активно на конец',r.active.length,'состояние на '+fmt(r.to))}${kpi('Провалено',r.failed.length,'за выбранный период',r.failed.length?'danger':'')}${kpi('Записей о работе',r.updateCount,'за выбранный период')}</div>`;}
function analyticsPage(){const r=Z.buildReport(state,ui.from,ui.to);return `${periodPicker()}${r.uncertainCount?historyNotice(r):''}${metricCards(r)}<section class="card">${heading('Работа по направлениям','',`${r.touched} задач с изменениями или записями в периоде · ${r.cancelled.length} отменено`)}<div class="table-wrap"><table><thead><tr><th>Направление</th><th>Завершено</th><th>Активно на конец</th><th>Провалено</th></tr></thead><tbody>${[...new Set([...Z.DIRECTIONS,...[...r.completed,...r.active,...r.failed].map(t=>t.direction),''])].map(d=>`<tr><td><b>${h(d||'Прочее')}</b></td><td>${r.completed.filter(t=>t.direction===d).length}</td><td>${r.active.filter(t=>t.direction===d).length}</td><td>${r.failed.filter(t=>t.direction===d).length}</td></tr>`).join('')}</tbody></table></div><p class="muted small">Считаются обычные задачи. Повторно открытая задача может иметь завершение в периоде и быть активной на его конец.</p></section><section class="card">${heading('CRM за выбранный период')}${crmComparison(r.crmStart,r.crmEnd)}</section><section class="card">${heading('Последние два среза CRM','', 'Независимо от выбранного периода; только фактические даты не позже сегодня')}${(()=>{const latest=[...state.crm].filter(c=>c.snapshotDate&&c.snapshotDate<=Z.today()).sort((a,b)=>b.snapshotDate.localeCompare(a.snapshotDate));const a=latest[0],b=latest.find(c=>c.snapshotDate!==a?.snapshotDate);return crmComparison(b,a);})()}</section>`;}
function crmComparison(a,b,compare=true){if(!b)return empty('Нет срезов с подтверждённой датой.');const val=(c,k)=>c?.stages?.[k]===""||c?.stages?.[k]==null?'—':c.stages[k];const delta=(x,y)=>typeof x==='number'&&typeof y==='number'?(y-x>0?'+':'')+(y-x):'—';const ca=Z.crmTotal(a),cb=Z.crmTotal(b);return `${compare?`<p class="muted small">Начало: ${a?fmt(a.snapshotDate):'нет данных'} · Конец: ${fmt(b.snapshotDate)}. Показаны последние известные состояния на границах периода.</p>`:`<div class="crm-summary"><span>На ${fmt(b.snapshotDate)}</span><strong>${cb??'—'}</strong><span>сделок${cb===null?' · заполнены не все стадии':''}</span></div>`}<div class="table-wrap"><table class="crm-table"><thead><tr><th>Стадия</th>${compare?`<th>${fmt(a?.snapshotDate)}</th>`:''}<th>${fmt(b.snapshotDate)}</th>${compare?'<th>Изменение</th>':''}</tr></thead><tbody>${Z.CRM_STAGES.map(k=>`<tr><td>${h(k)}</td>${compare?`<td>${h(val(a,k))}</td>`:''}<td>${h(val(b,k))}</td>${compare?`<td>${delta(val(a,k),val(b,k))}</td>`:''}</tr>`).join('')}<tr class="total-row"><td>Всего сделок</td>${compare?`<td>${ca??'—'}</td>`:''}<td>${cb??'—'}</td>${compare?`<td>${delta(ca,cb)}</td>`:''}</tr></tbody></table></div>${b.state?`<p class="muted">${plain(b.state)}</p>`:''}`;}
function selectedCrm(){return state.crm.find(c=>c.id===ui.crmId)||[...state.crm].filter(c=>!ui.crmMonth||(c.snapshotDate||c.month||'').startsWith(ui.crmMonth)).sort((a,b)=>(b.snapshotDate||'').localeCompare(a.snapshotDate||''))[0];}
function crmPage(){const snapshots=[...state.crm].sort((a,b)=>(b.snapshotDate||'').localeCompare(a.snapshotDate||'')),c=selectedCrm();return `<div class="card crm-picker">${input('Месяц для навигации','crmMonth',ui.crmMonth,'month','data-ui="crmMonth"')}${select('Срез','crmSelect',[['','Выберите срез'],...snapshots.filter(c=>!ui.crmMonth||(c.snapshotDate||c.month||'').startsWith(ui.crmMonth)).map(c=>[c.id,c.snapshotDate?fmt(c.snapshotDate)+(c.legacyDuplicate?' · проверить дубликат':''):'Дата не указана'+(c.month?' · '+c.month:'')])],c?.id||'','data-ui="crmId"')}</div>${c?`<section class="card"><div class="crm-edit-heading">${input('Фактическая дата среза','crmDate',c.snapshotDate,'date',`max="${Z.today()}" data-crm="snapshotDate"`)}<div class="crm-summary"><span>Всего сделок</span><strong id="crmTotal">${Z.crmTotal(c)??'—'}</strong></div></div>${c.legacyDuplicate||c.legacyFutureDate||c.legacyValues?`<div class="notice">Старые данные требуют уточнения.${c.legacyValues?' Исходные значения: '+h(JSON.stringify(c.legacyValues)):''}${c.legacyFutureDate?' Прежняя будущая дата: '+fmt(c.legacyFutureDate):''} ${c.legacyDuplicate?act('crm-remove','Удалить лишний срез',c.id,'small danger-btn'):''}</div>`:''}<p class="muted small">Пустое поле — нет данных. Ноль — проверено, сделок нет.</p><div class="crm-edit-grid">${Z.CRM_STAGES.map((s,i)=>input(s,'stage'+i,c.stages[s]??'','number',`min="0" step="1" inputmode="numeric" data-stage="${i}"`)).join('')}</div><div class="grid two">${area('Состояние базы','crmState',c.state,'data-crm="state"')}${area('Что изменилось','crmChanges',c.changes,'data-crm="changes"')}${area('Проблемы / нужна помощь','crmProblems',c.problems,'data-crm="problems"')}${area('Следующий шаг','crmNextStep',c.nextStep,'data-crm="nextStep"')}</div></section>`:`<section class="card">${empty('За этот месяц срезов нет. Создайте срез или выберите другой месяц.')}</section>`}<section class="card">${heading('История срезов')}<div class="table-wrap"><table><thead><tr><th>Дата</th><th>Всего</th><th>Состояние базы</th></tr></thead><tbody>${snapshots.map(c=>`<tr><td>${act('crm-open',c.snapshotDate?fmt(c.snapshotDate):'Уточнить дату',c.id,'text-btn')}</td><td>${Z.crmTotal(c)??'—'}</td><td>${h(short(c.state))}</td></tr>`).join('')}</tbody></table></div></section>`;}
function meetingsPage(){const meetings=[...state.meetings].sort((a,b)=>(b.date||'').localeCompare(a.date||'')),m=state.meetings.find(m=>m.id===ui.meetingId)||meetings[0];return `${m?`<section class="card">${select('Супервизия','meetingSelect',meetings.map(m=>[m.id,m.date?fmt(m.date):'Уточнить дату'+(m.legacyMonth?' · '+m.legacyMonth:'')]),m.id,'data-ui="meetingId"')}<div class="grid three">${input('Дата встречи','meetingDate',m.date,'date','data-meeting="date"')}${input('Начало отчётного периода','meetingPeriodStart',m.periodStart,'date','data-meeting="periodStart"')}${input('Следующая супервизия','meetingNext',m.nextMeeting,'date','data-meeting="nextMeeting"')}</div><div class="grid two">${area('Главные результаты','meetingResults',m.keyResults,'data-meeting="keyResults"')}${area('Трудности / вопросы','meetingDifficulties',m.difficulties,'data-meeting="difficulties"')}${area('Решения','meetingDecisions',m.decisions,'data-meeting="decisions"')}${area('Фокус следующего периода','meetingFocus',m.nextFocus,'data-meeting="nextFocus"')}</div><div class="actions"><button class="btn primary" data-action="meeting-report" data-value="${h(m.id)}" ${!m.date||!m.periodStart?'disabled':''}>Отчёт этой супервизии</button><button class="btn" data-action="meeting-plan" data-value="${h(m.id)}" ${!m.date||!m.nextMeeting?'disabled':''}>Планировать следующий период</button></div><p class="muted small">Следующий период начинается на следующий день после этой встречи — дни не учитываются дважды.</p></section>`:`<section class="card">${empty('Добавьте супервизию: дату, начало отчётного периода и решения.')}</section>`}<section class="card">${heading('Журнал встреч')}<div class="table-wrap"><table><thead><tr><th>Супервизия</th><th>Отчётный период</th><th>Главные результаты</th><th>Следующая</th></tr></thead><tbody>${meetings.map(m=>`<tr><td>${act('meeting-open',m.date?fmt(m.date):'Уточнить дату',m.id,'text-btn')}</td><td>${m.periodStart&&m.date?span(m.periodStart,m.date):'—'}</td><td>${h(short(m.keyResults))}</td><td>${fmt(m.nextMeeting)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function historyNotice(r){return `<div class="notice">У ${r.uncertainCount} задач нет полной истории до обновления. Старые состояния восстановлены по доступным данным. Даты без подтверждения не включаются в точные показатели.</div>`;}
function reportRows(rows){return rows.length?`<div class="table-wrap"><table class="report-table"><thead><tr><th>Задача</th><th>Состояние / результат</th><th>Работа в периоде</th><th>Дальше</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${h(t.title)}</b><small class="muted block">${h(t.id)} · ${h(t.direction||'Прочее')}<br>${h(t.projectName)}</small></td><td>${badge(t.status)}${t.eventDate?`<small class="block">${fmt(t.eventDate)}</small>`:''}<p>${plain(t.result)}</p>${t.blocker?`<small>Препятствие: ${plain(t.blocker)}</small>`:''}</td><td>${t.updates?.length?t.updates.map(u=>`<p><small>${fmt(u.date)}</small><br>${plain(u.text)}</p>`).join(''):'Отдельных записей за период нет.'}</td><td>${plain(t.nextStep)}</td></tr>`).join('')}</tbody></table></div>`:empty('Нет задач в этой категории.');}
function reportDocument(r,saved=null){return `<article class="report-document" id="periodReport"><header class="report-cover"><div class="report-brand"><svg width="36" height="36" viewBox="0 0 512 512" aria-hidden="true"><rect width="512" height="512" rx="116" fill="#5b5ce2"/><path d="m132 250 78 78 168-174" fill="none" stroke="#fff" stroke-width="48" stroke-linecap="round" stroke-linejoin="round"/><path d="M284 374h95" fill="none" stroke="#fff" stroke-width="34" stroke-linecap="round"/></svg>Задачник <span>/ Рабочая супервизия</span></div><h1>${span(r.from,r.to)}</h1><p>Работа, результаты и следующие шаги</p><small>${saved?'Зафиксировано '+new Date(saved.savedAt).toLocaleString('ru-RU')+' · версия '+saved.version:'Текущий расчёт · '+fmt(Z.today())}</small></header>${r.uncertainCount?historyNotice(r):''}${metricCards(r)}<section>${heading('01 · Главные результаты')}<p>${plain(r.meeting?.keyResults,'')}</p></section><section>${heading('02 · Завершённая работа')}${reportRows(r.completed)}</section><section>${heading('03 · Активно на конец периода','', 'Включая задачи, которые были завершены уже после конца этого периода')}${reportRows(r.active)}</section><section>${heading('04 · Не выполнено и отменено')}${r.failed.length?'<h3>Провалено</h3>'+reportRows(r.failed):''}${r.cancelled.length?'<h3>Отменено</h3>'+reportRows(r.cancelled):''}${!r.failed.length&&!r.cancelled.length?empty('Проваленных и отменённых задач за период нет.'):''}</section>${r.undated?.length?`<section>${heading('Даты требуют уточнения')}<p class="muted">Месячные итоги без точного дня; в счётчики завершения не включены.</p>${reportRows(r.undated)}</section>`:''}<section>${heading('05 · CRM ПСТБИ')}${crmComparison(r.crmStart,r.crmEnd)}${r.crmEnd?`<div class="grid two"><div><h3>Что изменилось</h3><p>${plain(r.crmEnd.changes)}</p></div><div><h3>Следующий шаг</h3><p>${plain(r.crmEnd.nextStep)}</p></div></div>`:''}</section><section>${heading('06 · Решения и следующий период')}<div class="grid two"><div><h3>Трудности / вопросы</h3><p>${plain(r.meeting?.difficulties)}</p></div><div><h3>Решения</h3><p>${plain(r.meeting?.decisions)}</p></div></div><h3>Фокус</h3><p>${plain(r.meeting?.nextFocus||r.plan?.focus)}</p>${r.plan?`<h3>План ${span(r.plan.startDate,r.plan.endDate)}</h3><ul>${r.plan.tasks.map(t=>`<li>${h(t.title)}${t.deadline?' · до '+fmt(t.deadline):''}</li>`).join('')}</ul>`:''}</section><p class="muted small">Завершение — событие в периоде. Активность — состояние на его конец. Группы и предложения в показатели выполнения не входят.</p></article>`;}
function currentReport(){const saved=state.reports.find(r=>r.id===ui.reportId);return {saved,data:saved?saved.data:Z.buildReport(state,ui.from,ui.to,ui.reportMeetingId)};}
function reportsPage(){const {saved,data}=currentReport();const versions=[...state.reports].sort((a,b)=>b.savedAt.localeCompare(a.savedAt));return `${periodPicker()}<section class="card report-controls">${select('Отчёт','reportVersion',[['','Текущий расчёт'],...versions.map(r=>[r.id,span(r.from,r.to)+' · версия '+r.version])],ui.reportId,'data-ui="reportId"')}${select('Решения супервизии','reportMeeting',[['','Без привязки к встрече'],...state.meetings.filter(m=>m.date===ui.to&&m.periodStart===ui.from).map(m=>[m.id,fmt(m.date)])],ui.reportMeetingId,`data-ui="reportMeetingId" ${saved?'disabled':''}`)}<div class="actions">${act('save-report',saved?'Сохранить новую версию':'Зафиксировать отчёт','','primary')}${act('print','Печать / PDF')}${act('download-report','Скачать HTML')}${act('export-tasks','Задачи CSV')}${act('export-crm','CRM CSV')}</div><p class="muted small">${saved?'Показана сохранённая версия. Последующие изменения задач её не меняют.':'Зафиксируйте отчёт перед супервизией: он сохранится в таком виде.'}</p></section>${reportDocument(data,saved)}`;}
function settingsPage(){return `<section class="card">${heading('Ваши данные')}<p>Данные сохраняются в этом браузере на этом адресе. Для переноса на другой компьютер используйте JSON-копию.</p><div class="actions">${act('backup','Скачать JSON-копию','','primary')}<label class="btn">Импорт JSON<input type="file" accept=".json,application/json" data-import hidden></label></div><p class="muted small">Изменения обновляют открытые разделы и другие вкладки этого браузера. Синхронизация между устройствами не подключена.</p></section><section class="card">${heading('Автоматические резервные копии','', 'Создаются перед обновлением, импортом и восстановлением. Хранятся последние пять.')}<div class="backup-list">${ZStore.backups().map(b=>`<div class="backup-row"><div><b>${h(b.reason)}</b><small>${new Date(b.createdAt).toLocaleString('ru-RU')}</small></div><div class="actions">${act('download-backup','Скачать',b.id,'small')}${act('restore-backup','Восстановить',b.id,'small')}</div></div>`).join('')||empty('Резервных копий пока нет.')}</div></section>${state.migrationWarnings?.length?`<section class="card">${heading('Проверка старых данных')}<ul class="help-list">${state.migrationWarnings.map(w=>`<li>${h(w)}</li>`).join('')}</ul><div class="actions">${act('nav','Открыть задачи','tasks')}${act('nav','Открыть CRM','crm')}${act('nav','Открыть супервизии','meetings')}</div></section>`:''}<section class="card">${heading('Как устроена работа')}<div class="help-grid"><div><b>Одна задача на всё время</b><p>Меняйте сроки и статус в её карточке. Родителя и дочерние задачи можно открыть по клику. Группа показывает прогресс своих задач.</p></div><div><b>Ход работы и результат</b><p>Вносите датированные заметки во время работы. Итог заполняйте в поле «Результат». Повторное открытие сохраняет завершение в истории.</p></div><div><b>Период любой длины</b><p>Отчёт и аналитика используют общие даты. Для соседних периодов следующий день после встречи исключает двойной учёт.</p></div><div><b>История остаётся</b><p>Архивируйте ненужные задачи. Завершения, заметки и сохранённые отчёты сохранятся. Для отказа от задачи используйте «Отменено».</p></div></div></section>`;}
function recovery(){return `<main class="recovery"><img src="icon.svg" width="64" alt=""><h1>Восстановление данных</h1><p class="error-text">${h(ZStore.error)}</p><p>Исходные данные сохранены. Выберите проверенную резервную копию для восстановления.</p><div class="actions">${act('raw-backup','Скачать исходные данные')}<label class="btn primary">Загрузить JSON<input type="file" accept=".json,application/json" data-import hidden></label></div>${ZStore.backups().map(b=>`<p>${h(b.reason)} ${act('restore-backup','Восстановить',b.id,'small')}</p>`).join('')}${ui.modal==='import'?importPanel():''}</main>`;}
function nextId(code){let n=1;while(Z.task(state,code+'-'+String(n).padStart(2,'0')))n++;return code+'-'+String(n).padStart(2,'0');}
function openTask(id=null,projectCode=''){
 ui.editId=id;ui.modal='task';ui.error='';ui.statusDate=Z.today();
 const p=projectCode||ui.filters.project||state.projects[0]?.code||'';
 ui.draft=id?Z.clone(Z.task(state,id)):{id:nextId(p||'TASK'),projectCode:p,title:'',type:'Задача',parentId:'',status:'Запланировано',priority:'',startDate:'',deadline:'',completedAt:'',result:'',blocker:'',nextStep:''};ui.updateDraft={date:Z.today(),text:''};render();document.querySelector('#taskTitle')?.focus();
}
function modalFrame(title,body,wide=false){return `<div class="modal-layer"><div class="modal-backdrop" data-action="close-modal"></div><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle" tabindex="-1"><header class="modal-header"><div><span class="eyebrow">Задачник</span><h2 id="modalTitle">${h(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></header>${ui.error?`<div class="notice danger" role="alert">${h(ui.error)}</div>`:''}${body}</section></div>`;}
function renderModal(){
 if(!ui.modal)return '';
 if(ui.modal==='task')return modalFrame(ui.editId?'Карточка задачи':'Новая задача',taskForm(),true);
 if(ui.modal==='project')return modalFrame(ui.editId?'Изменить проект':'Новый проект',projectForm());
 if(ui.modal==='crm')return modalFrame('Новый срез CRM',`<form data-form="crm"><p class="muted">Один срез на день. Старый срез можно открыть и уточнить.</p>${input('Дата среза','newCrmDate',ui.draft.date,'date',`required max="${Z.today()}" data-draft="date"`)}<label class="check-field"><input type="checkbox" data-draft="copy" ${ui.draft.copy?'checked':''}>Скопировать стадии из последнего среза не позже этой даты</label><button class="btn primary" type="submit">Создать срез</button></form>`);
 if(ui.modal==='meeting')return modalFrame('Новая супервизия',`<form data-form="meeting">${input('Дата встречи','newMeetingDate',ui.draft.date,'date','required data-draft="date"')}${input('Начало отчётного периода','newMeetingStart',ui.draft.periodStart,'date','required data-draft="periodStart"')}<p class="muted small">Если предыдущий отчёт закончился 2 ноября, новый начинается 3 ноября.</p><button class="btn primary" type="submit">Создать супервизию</button></form>`);
 if(ui.modal==='import')return modalFrame('Проверка импорта',importPanel());
 return '';
}
function taskForm(){const t=ui.draft,live=ui.editId?Z.task(state,ui.editId):null,children=live?state.tasks.filter(x=>x.parentId===t.id):[],parent=Z.task(state,t.parentId);const forbidden=live?Z.descendants(state,t.id):new Set();forbidden.add(t.id);
 return `<form data-form="task"><div class="task-id-head"><span>${ui.editId?'ID '+h(t.id):'Новая запись'}</span>${ui.editId?act('copy',icon('copy')+'Копировать ID',t.id,'small quiet'):''}<span class="muted small">${ui.editId?'Изменения сохраняются автоматически':''}</span></div>${input('Название','taskTitle',t.title,'text','required data-task="title" placeholder="Что нужно сделать?"')}${!ui.editId?input('ID задачи','taskId',t.id,'text','required data-task="id"'):''}<div class="grid two">${select('Проект','taskProject',state.projects.map(p=>[p.code,p.name]),t.projectCode,'data-task="projectCode"')}${select('Тип','taskType',Z.TYPES,t.type,'data-task="type"')}${select('Статус','taskStatus',Z.STATUSES,t.status,'data-task="status"')}${select('Приоритет','taskPriority',[['','Не указан'],'Высокий','Средний','Низкий'],t.priority,'data-task="priority"')}</div><div class="grid three">${input('Начало работы','taskStart',t.startDate,'date','data-task="startDate"')}${input('Дедлайн','taskDeadline',t.deadline,'date','data-task="deadline"')}${input('Дата изменения','taskStatusDate',ui.statusDate,'date',`max="${Z.today()}" data-ui="statusDate"`)}</div><p class="muted small">«Дата изменения» определяет, с какого дня правка попадает в историю. Дедлайн может быть любым.</p><section class="form-section"><h3>Связи</h3>${select('Родительская задача','taskParent',[['','Без родителя'],...state.tasks.filter(x=>!forbidden.has(x.id)).map(x=>[x.id,x.id+' · '+short(x.title,70)])],t.parentId,'data-task="parentId"')}${parent?`<div class="relation-row"><span>Родитель</span>${act('related-task',h(parent.title),parent.id,'text-btn')}</div>`:''}${live?.type==='Группа задач'?`<p class="muted">Прогресс: ${groupProgress(live.id)}</p>`:''}${children.length?`<div class="related-list"><span class="muted small">Дочерние задачи</span>${children.map(x=>`<div class="relation-row">${act('related-task',h(x.id+' · '+x.title),x.id,'text-btn')}${badge(x.status)}</div>`).join('')}</div>`:''}${live?act('new-child',icon('plus')+'Добавить дочернюю',live.id,'small'):''}</section><section class="form-section"><h3>Результат</h3><div class="grid two">${input('Дата завершения / закрытия','taskCompleted',t.completedAt,'date',`max="${Z.today()}" data-task="completedAt" ${!Z.CLOSED.includes(t.status)?'disabled':''}`)}${live&&Z.isActive(live)?`<div class="align-bottom">${act('quick-done',icon('check')+'Завершить задачу',live.id,'primary')}</div>`:''}</div>${live?.unknownCompletionMonth?`<div class="notice">Результат перенесён за ${h(live.unknownCompletionMonth)}. Укажите точную дату закрытия — она появится в отчётности.</div>`:''}${area('Что получилось','taskResult',t.result,'data-task="result" placeholder="Итог можно внести сразу после завершения"')}<div class="grid two">${area('Что мешает / нужна помощь','taskBlocker',t.blocker,'data-task="blocker"')}${area('Следующий шаг','taskNextStep',t.nextStep,'data-task="nextStep"')}</div></section>${!ui.editId?'<button class="btn primary" type="submit">Создать задачу</button>':''}</form>${live?`<section class="form-section"><h3>Ход работы</h3><form data-form="update">${input('Дата записи','updateDate',ui.updateDraft.date,'date',`max="${Z.today()}" required data-update="date"`)}${area('Что сделано','updateText',ui.updateDraft.text,'required data-update="text" placeholder="Короткая запись о продвижении задачи"')}<button class="btn" type="submit">Добавить запись</button></form><div class="timeline">${state.updates.filter(u=>u.taskId===live.id).sort((a,b)=>(b.date||b.legacyMonth).localeCompare(a.date||a.legacyMonth)).map(u=>`<div class="timeline-item"><small>${u.date?fmt(u.date):h(u.legacyMonth)+' · точный день не указан'}</small><p>${plain(u.text)}</p>${!u.date?input('Уточнить дату','legacyUpdate'+h(u.id),'','date',`max="${Z.today()}" data-legacy-update="${h(u.id)}"`):''}</div>`).join('')||'<p class="muted">Записей пока нет.</p>'}</div></section><details class="form-section"><summary>История изменений · ${live.history.length}</summary>${live.historyIncomplete?'<p class="muted small">До обновления история не велась. Доступные старые данные отмечены как восстановленные.</p>':''}<div class="timeline">${[...Z.sortEvents(live.history)].reverse().map(e=>`<div class="timeline-item"><small>${fmt(e.date)}${e.source?' · восстановлено':''}</small><p>${Object.entries(e.changes).map(([k,v])=>`${h(fieldLabel(k))}: ${h(k==='archived'?(v?'в архиве':'восстановлено'):v||'—')}`).join('<br>')}</p></div>`).join('')||'<p class="muted">Изменений пока нет.</p>'}</div></details><div class="modal-footer">${act('archive',live.archived?'Вернуть из архива':'В архив',live.id,'quiet')}${act('close-modal','Готово','','primary')}</div>`:''}`;
}
function fieldLabel(k){return {title:'Название',projectCode:'Проект',parentId:'Родитель',type:'Тип',status:'Статус',priority:'Приоритет',startDate:'Начало',deadline:'Дедлайн',completedAt:'Завершение',result:'Результат',blocker:'Препятствие',nextStep:'Следующий шаг',archived:'Архив'}[k]||k;}
function projectForm(){const p=ui.draft;return `<form data-form="project">${input('Код','projectCode',p.code,'text',`required data-draft="code" ${ui.editId?'readonly':''}`)}${input('Название','projectName',p.name,'text','required data-draft="name"')}${select('Направление','projectDirection',[['','Без направления · Прочее'],...Z.DIRECTIONS],p.direction,'data-draft="direction"')}${select('Тип','projectType',['Проект','Постоянная работа'],p.type,'data-draft="type"')}<div class="actions"><button class="btn primary" type="submit">Сохранить проект</button>${ui.editId?act('delete-project','Удалить пустой проект',ui.editId,'danger-btn'):''}</div></form>`;}
function importPanel(){const d=ui.importData;return d?`<p><b>${h(ui.importName)}</b></p><div class="import-summary"><span>${d.projects.length} проектов</span><span>${d.tasks.length} задач</span><span>${d.crm.length} срезов CRM</span><span>${d.meetings.length} супервизий</span><span>${d.reports.length} сохранённых отчётов</span></div><p>Эти данные заменят текущую базу. Перед заменой автоматически сохранится резервная копия.</p>${d.migrationWarnings?.length?`<details><summary>Замечания при переносе</summary><ul>${d.migrationWarnings.map(w=>`<li>${h(w)}</li>`).join('')}</ul></details>`:''}<div class="actions">${act('confirm-import','Заменить данные','','primary')}${act('close-modal','Отмена')}</div>`:'';}
function closeModal(){if(ui.error&&!confirm('Некоторые изменения не сохранены. Закрыть карточку?'))return;if(!ui.editId&&ui.modal==='task'&&ui.draft?.title&&!confirm('Закрыть без создания задачи?'))return;ui.modal=null;ui.draft=null;ui.editId=null;ui.error='';render();}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadJSON(data,name='zadachnik_backup_'+Z.today()+'.json'){download(name,JSON.stringify(data,null,2),'application/json');}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(';')).join('\r\n');}
async function copy(text){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw Error();}catch{const a=document.createElement('textarea');a.value=text;a.style.position='fixed';a.style.opacity='0';document.body.append(a);a.select();const ok=document.execCommand('copy');a.remove();if(!ok)return toast('Не удалось скопировать. Выделите ID вручную.',true);}toast('ID скопирован');}
async function previewImport(file){if(!file)return;try{if(file.size>20*1024*1024)throw Error('Файл больше 20 МБ.');const d=Z.migrate(JSON.parse(await file.text()));ui.importData=d;ui.importName=file.name;ui.modal='import';ui.error='';render();}catch(e){toast('Импорт отклонён: '+e.message,true);}}
function openMeetingReport(id){const m=state.meetings.find(x=>x.id===id);Z.period(m.periodStart,m.date);ui.from=m.periodStart;ui.to=m.date;ui.reportMeetingId=m.id;ui.reportId='';ui.periodDraft=null;ui.page='reports';render();}
function resetFilters(){ui.filters={status:'active',time:'all',dateField:'deadline',direction:'all',project:'',search:'',type:''};}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const action=b.dataset.action,v=b.dataset.value;
 try{
 switch(action){
 case 'nav':ui.page=v;ui.mobile=false;ui.periodDraft=null;ui.error='';render();window.scrollTo(0,0);break;
 case 'collapse':ui.collapsed=!ui.collapsed;try{localStorage.setItem('supervision-menu-collapsed',String(ui.collapsed));}catch{}render();break;
 case 'mobile-open':ui.mobile=true;render();break;
 case 'mobile-close':ui.mobile=false;render();break;
 case 'dismiss-tab':ui.tabNotice='';render();break;
 case 'new-task':if(!state.projects.length){toast('Сначала создайте проект.');ui.page='projects';render();}else openTask();break;
 case 'task':openTask(v);break;
 case 'related-task':if(ui.error)return toast('Исправьте несохранённое поле перед переходом.',true);openTask(v);break;
 case 'new-child':{const p=Z.task(state,v);openTask(null,p.projectCode);ui.draft.parentId=p.id;render();break;}
 case 'close-modal':closeModal();break;
 case 'copy':await copy(v);break;
 case 'quick-done':{const r=commit(d=>Z.patchTask(d,v,{status:'Завершено',completedAt:ui.statusDate},ui.statusDate),{renderNow:false});if(r.ok){ui.draft=Z.clone(Z.task(state,v));ui.error='';render();document.querySelector('#taskResult')?.focus();}break;}
 case 'archive':{const t=Z.task(state,v);const r=commit(d=>Z.patchTask(d,v,{archived:!t.archived},Z.today()));if(r.ok){ui.modal=null;render();toast(t.archived?'Задача возвращена':'Задача в архиве. История сохранена.');}break;}
 case 'direction':resetFilters();ui.filters.direction=v;ui.page='tasks';render();break;
 case 'overdue':resetFilters();ui.filters.time='overdue';ui.page='tasks';render();break;
 case 'week':resetFilters();ui.filters.time='week';ui.page='tasks';render();break;
 case 'completed-since':case 'current-report':{const m=latestMeeting();if(m&&m.date<Z.today())ui.from=Z.addDays(m.date,1);else ui.from=Z.calendarMonth()[0];ui.to=Z.today();ui.reportId='';ui.reportMeetingId='';ui.periodDraft=null;ui.page='reports';render();break;}
 case 'new-project':ui.modal='project';ui.editId=null;ui.draft={code:'',name:'',direction:'',type:'Проект'};ui.error='';render();break;
 case 'project-edit':ui.modal='project';ui.editId=v;ui.draft=Z.clone(Z.project(state,v));ui.error='';render();break;
 case 'project-new-task':openTask(null,v);break;
 case 'project-tasks':resetFilters();ui.filters.project=v;ui.page='tasks';render();break;
 case 'delete-project':if(state.tasks.some(t=>t.projectCode===v))throw Error('В проекте есть задачи, включая архив. Сначала перенесите их.');if(confirm('Удалить пустой проект?')){const r=commit(d=>{d.projects=d.projects.filter(p=>p.code!==v);});if(r.ok){ui.modal=null;render();}}break;
 case 'preset':{const planning=v.startsWith('plan-'),key=v.replace('plan-','');let [from,to]=key==='month'?Z.calendarMonth():[Z.today(),Z.addDays(Z.today(),6)];if(!planning&&key==='week')[from,to]=[Z.addDays(Z.today(),-6),Z.today()];if(!planning&&key==='month')to=Z.today();if(key==='meeting'){const m=latestMeeting();if(!m)throw Error('Сначала добавьте дату супервизии.');from=m.date<Z.today()?Z.addDays(m.date,1):m.date;to=Z.today();}if(planning){ui.planFrom=from;ui.planTo=to;}else{ui.from=from;ui.to=to;ui.reportId='';ui.reportMeetingId='';}ui.periodDraft=null;render();break;}
 case 'plan-add':commit(d=>{const c=ensureCycle(d);if(!c.taskIds.includes(v))c.taskIds.push(v);});break;
 case 'plan-remove':commit(d=>{const c=ensureCycle(d);c.taskIds=c.taskIds.filter(id=>id!==v);});break;
 case 'new-crm':ui.modal='crm';ui.editId=null;ui.error='';ui.draft={date:Z.today(),copy:false};render();break;
 case 'crm-open':ui.crmId=v;ui.crmMonth='';ui.page='crm';render();break;
 case 'crm-remove':if(confirm('Удалить этот срез? Перед удалением будет сохранена резервная копия.')){ZStore.backup(ZStore.raw(),'Перед удалением среза CRM');commit(d=>{d.crm=d.crm.filter(c=>c.id!==v);});ui.crmId='';render();}break;
 case 'new-meeting':ui.modal='meeting';ui.editId=null;ui.error='';{const last=latestMeeting();ui.draft={date:Z.today(),periodStart:last&&last.date<Z.today()?Z.addDays(last.date,1):Z.calendarMonth()[0]};}render();break;
 case 'meeting-open':ui.meetingId=v;render();break;
 case 'meeting-report':openMeetingReport(v);break;
 case 'meeting-plan':{const m=state.meetings.find(x=>x.id===v);ui.planFrom=Z.addDays(m.date,1);ui.planTo=m.nextMeeting;Z.period(ui.planFrom,ui.planTo);commit(d=>{const c=ensureCycle(d);if(!c.focus)c.focus=m.nextFocus||'';},{renderNow:false});ui.page='planning';ui.periodDraft=null;render();break;}
 case 'save-report':{if(ui.to>Z.today())throw Error('Можно зафиксировать отчёт только по наступившим датам.');const r=commit(d=>Z.saveReport(d,ui.from,ui.to,ui.reportMeetingId),{renderNow:false});if(r.ok){ui.reportId=r.value.id;render();toast('Отчёт зафиксирован. Эта версия не изменится.');}break;}
 case 'print':window.print();break;
 case 'download-report':{const r=currentReport();download(`zadachnik_report_${r.data.from}_${r.data.to}${r.saved?'_v'+r.saved.version:''}.html`,'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Отчёт '+h(span(r.data.from,r.data.to))+'</title><style>body{font:15px/1.6 system-ui,sans-serif;color:#182230;margin:30px auto;max-width:1100px;padding:0 20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #e4e7ef;vertical-align:top}h1{font-size:32px}h2{font-size:21px;margin-top:35px}.kpis,.grid{display:flex;gap:25px}.kpi{flex:1;background:#f6f7fb;padding:18px}.kpi strong{display:block;font-size:30px}.kpi small,.muted{color:#68738a}.kpi span,.kpi small{display:block}.block{display:block}.report-brand{color:#5b5ce2}.report-brand img{display:none}.notice{background:#fff8e6;padding:16px}.badge{font-size:12px}.table-wrap{overflow:auto}.report-document section{margin:24px 0}button{display:none}@media print{body{margin:0;font-size:10pt}table{font-size:9pt}tr{break-inside:avoid}.kpis{display:flex}.report-cover{break-after:avoid}h2{break-after:avoid}}@media(max-width:600px){.kpis,.grid{display:block}.kpi{margin-bottom:10px}}</style><body>'+reportDocument(r.data,r.saved)+'</body></html>','text/html;charset=utf-8');break;}
 case 'export-tasks':{const r=currentReport().data;const rows=[['Категория','ID','Проект','Задача','Статус на дату','Дата события','Результат','Что сделано','Следующий шаг']];for(const [key,label]of [['completed','Завершено'],['active','Активно на конец'],['failed','Провалено'],['cancelled','Отменено'],['undated','Уточнить дату']])for(const t of r[key]||[])rows.push([label,t.id,t.projectName,t.title,t.status,t.eventDate||'',t.result,(t.updates||[]).map(u=>fmt(u.date)+': '+u.text).join(' | '),t.nextStep]);download(`tasks_${r.from}_${r.to}.csv`,csv(rows),'text/csv;charset=utf-8');break;}
 case 'export-crm':{const r=currentReport().data;const rows=[['Граница','Дата среза',...Z.CRM_STAGES,'Всего']];for(const [key,label]of [['crmStart','Начало'],['crmEnd','Конец']]){const c=r[key];rows.push([label,c?.snapshotDate||'',...Z.CRM_STAGES.map(s=>c?.stages[s]??''),Z.crmTotal(c)??'']);}download(`crm_${r.from}_${r.to}.csv`,csv(rows),'text/csv;charset=utf-8');break;}
 case 'backup':downloadJSON(state);break;
 case 'raw-backup':download('zadachnik_original_data.json',ZStore.raw()||'','application/json');break;
 case 'download-backup':{const b=ZStore.backups().find(b=>b.id===v);download('zadachnik_backup_'+b.createdAt.slice(0,10)+'.json',b.raw,'application/json');break;}
 case 'restore-backup':{const b=ZStore.backups().find(b=>b.id===v);ui.importData=Z.migrate(JSON.parse(b.raw));ui.importName='Автоматическая копия: '+b.reason;ui.modal='import';ui.error='';render();break;}
 case 'confirm-import':ZStore.replace(ui.importData,'Перед импортом / восстановлением');state=ZStore.state;ui.modal=null;ui.importData=null;ui.crmId='';ui.meetingId='';ui.reportId='';ui.reportMeetingId='';ui.savingError='';ui.page='dashboard';resetFilters();render();toast('Данные восстановлены.');break;
 }
 }catch(err){ui.error=err.message;toast(err.message,true);render();}
});
function setTaskField(key,value){ui.draft[key]=value;ui.error='';if(!ui.editId){if(key==='projectCode')ui.draft.id=nextId(value);if(key==='status')ui.draft.completedAt=Z.CLOSED.includes(value)?ui.statusDate:'';render();return;}
 let r;if(key==='completedAt')r=commit(d=>Z.setClosureDate(d,ui.editId,value),{renderNow:false});else r=commit(d=>Z.patchTask(d,ui.editId,{[key]:value},ui.statusDate),{renderNow:false});
 if(r.ok){ui.draft=Z.clone(Z.task(state,ui.editId));ui.error='';}else ui.error=ui.savingError;render();
}
function handleInput(e){const el=e.target;if(el.type==='file')return;if(['date','month'].includes(el.type)&&e.type==='input')return;if(!['date','month','file'].includes(el.type)&&e.type==='change')return;
 const value=el.type==='checkbox'?el.checked:el.value;
 if(el.dataset.task){setTaskField(el.dataset.task,value);return;}
 if(el.dataset.draft){ui.draft[el.dataset.draft]=value;return;}
 if(el.dataset.update){ui.updateDraft[el.dataset.update]=value;return;}
 if(el.dataset.period){if(!ui.periodDraft)ui.periodDraft={planning:ui.page==='planning',from:ui.page==='planning'?ui.planFrom:ui.from,to:ui.page==='planning'?ui.planTo:ui.to};ui.periodDraft[el.dataset.period]=value;ui.periodDraft.error='';return;}
 if(el.dataset.filter){const filters=currentFilters();filters[el.dataset.filter]=value;if(el.dataset.filter==='status'&&['completed','failed','cancelled'].includes(value))filters.dateField='completedAt';if(el.dataset.filter==='status'&&value==='active')filters.dateField='deadline';render();return;}
 if(el.dataset.ui){const key=el.dataset.ui;if(key==='planId'){const c=state.cycles.find(c=>c.id===value);if(c){ui.planFrom=c.startDate;ui.planTo=c.endDate;ui.periodDraft=null;}}
 else {ui[key]=value;if(key==='crmMonth')ui.crmId='';if(key==='reportId'){const r=state.reports.find(r=>r.id===value);if(r){ui.from=r.from;ui.to=r.to;ui.reportMeetingId=r.meetingId;ui.periodDraft=null;}}}render();return;}
 if(el.dataset.cycle){commit(d=>{ensureCycle(d)[el.dataset.cycle]=value;});return;}
 if(el.dataset.stage!==undefined){const id=selectedCrm()?.id,k=Z.CRM_STAGES[Number(el.dataset.stage)],n=value===''?'':Number(value);if(value!==''&&(!Number.isSafeInteger(n)||n<0)){el.setCustomValidity('Введите целое неотрицательное число.');el.reportValidity();ui.savingError='Количество CRM не сохранено: нужно целое неотрицательное число.';document.querySelector('.save-status').textContent='Не сохранено';return;}el.setCustomValidity('');commit(d=>{const c=d.crm.find(c=>c.id===id);c.stages[k]=n;});return;}
 if(el.dataset.crm){const id=selectedCrm()?.id;commit(d=>{const c=d.crm.find(c=>c.id===id);c[el.dataset.crm]=value;if(el.dataset.crm==='snapshotDate'){c.month=value.slice(0,7);c.legacyUndated=!value;c.legacyDuplicate=false;delete c.legacyFutureDate;Z.validateCrm(d,c);}});return;}
 if(el.dataset.meeting){const m=state.meetings.find(m=>m.id===ui.meetingId)||[...state.meetings].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];commit(d=>{const x=d.meetings.find(x=>x.id===m.id);x[el.dataset.meeting]=value;if(el.dataset.meeting==='date')x.legacyUndated=!value;Z.validateMeeting(x);});return;}
 if(el.dataset.legacyUpdate){commit(d=>{const u=d.updates.find(u=>u.id===el.dataset.legacyUpdate);if(!Z.validDate(value)||value>Z.today())throw Error('Укажите фактическую дату.');u.date=value;delete u.legacyMonth;});}
}
document.addEventListener('input',handleInput);
document.addEventListener('change',e=>{if(e.target.matches('[data-import]'))previewImport(e.target.files[0]);else handleInput(e);});
document.addEventListener('submit',e=>{
 const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form;ui.error='';
 try{
 if(type==='period'){const planning=f.dataset.planning==='true',from=f.querySelector('#periodFrom').value,to=f.querySelector('#periodTo').value;Z.period(from,to);if(!planning&&to>Z.today())throw Error('Отчётность доступна по наступившим датам; будущую работу выберите в планировании.');if(planning){ui.planFrom=from;ui.planTo=to;}else{ui.from=from;ui.to=to;ui.reportId='';ui.reportMeetingId='';}ui.periodDraft=null;render();return;}
 if(type==='task'&&!ui.editId){const r=commit(d=>Z.newTask(d,ui.draft),{renderNow:false});if(r.ok)openTask(r.value.id);else{ui.error=ui.savingError;render();}return;}
 if(type==='update'){const r=commit(d=>Z.addUpdate(d,ui.editId,ui.updateDraft.date,ui.updateDraft.text),{renderNow:false});if(r.ok){ui.updateDraft={date:Z.today(),text:''};render();}return;}
 if(type==='project'){const p=ui.draft;if(!p.code.trim()||!p.name.trim())throw Error('Укажите код и название проекта.');const r=commit(d=>{if(ui.editId){Object.assign(Z.project(d,ui.editId),{name:p.name.trim(),direction:p.direction,type:p.type});}else{if(d.projects.some(x=>x.code===p.code.trim()))throw Error('Такой код уже существует.');d.projects.push({...p,code:p.code.trim(),name:p.name.trim()});}},{renderNow:false});if(r.ok){ui.modal=null;render();}else{ui.error=ui.savingError;render();}return;}
 if(type==='crm'){const r=commit(d=>Z.newCrm(d,ui.draft.date,ui.draft.copy),{renderNow:false});if(r.ok){ui.crmId=r.value.id;ui.crmMonth='';ui.modal=null;ui.page='crm';render();}else{ui.error=ui.savingError;render();}return;}
 if(type==='meeting'){const m={id:Z.uid(),...ui.draft,keyResults:'',difficulties:'',decisions:'',nextFocus:'',nextMeeting:''};Z.validateMeeting(m);if(state.meetings.some(x=>x.date===m.date))throw Error('Супервизия на эту дату уже существует. Откройте её для изменения.');const r=commit(d=>d.meetings.push(m),{renderNow:false});if(r.ok){ui.meetingId=m.id;ui.modal=null;ui.page='meetings';render();}return;}
 }catch(err){ui.error=err.message;if(type==='period')ui.periodDraft={planning:ui.page==='planning',from:f.querySelector('#periodFrom').value,to:f.querySelector('#periodTo').value,error:err.message};render();toast(err.message,true);}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(ui.modal)closeModal();else if(ui.mobile){ui.mobile=false;render();}}if(e.key==='Tab'&&ui.modal){const items=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal summary')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
// Подписка сохраняет набранный текст при приходе изменений из другой вкладки.
window.addEventListener('storage',e=>{if(e.key!==ZStore.KEY)return;state=ZStore.state;ui.tabNotice=ZStore.error||'Данные обновлены в другой вкладке.';if(ui.editId&&ui.modal==='task'&&!ui.error){const current=Z.task(state,ui.editId);if(current)ui.draft=Z.clone(current);}render();});
render();
